<script setup>
const route=useRoute(),{user,send,busy,fa}=useReiki()
const {data:course,error,refresh}=await useFetch('/api/catalog/courses',{query:{id:route.params.id}})
const opened=ref(null)
async function purchase(){if(!user.value)return navigateTo('/profile');await send('/api/account/purchases',{kind:'course',id:course.value.id})}
async function complete(l){if(!user.value)return navigateTo('/profile');if(await send('/api/account/progress',{kind:'lesson',id:l.id,position:0,done:true}))await refresh()}
</script>
<template><main class="page"><NuxtLink to="/reiki" class="back">→ مسیر ریکی</NuxtLink><p v-if="error" class="state">دوره یافت نشد یا ارتباط قطع است.</p><template v-if="course"><div class="page-heading"><small>{{course.instructor}}</small><h1>{{course.title}}</h1><p>{{course.description}}</p></div><section class="card"><template v-if="course.owned"><h3>پیشرفت شما: {{fa(course.percent)}}٪</h3><progress :value="course.percent" max="100"/></template><template v-else><p>این دوره مستقل از عضویت ویژه است.</p><button class="btn btn-gold" :disabled="busy" @click="purchase">درخواست خرید · {{fa(course.price)}} تومان</button><small class="block">درگاه فعال نیست؛ درخواست منتظر تأیید دستی مدیر می‌ماند.</small></template></section><section class="section stack"><article v-for="l in course.lessons" :key="l.id" class="card"><small>{{l.module_title}} · {{l.is_preview?'پیش‌نمایش رایگان':l.done?'تکمیل شده':l.access.unlocked?'آمادهٔ مطالعه':'قفل است'}}</small><button class="event-button" :disabled="!l.access.unlocked" :aria-expanded="opened===l.id" @click="opened=opened===l.id?null:l.id"><h3>{{l.title}}</h3><span>{{l.done?'✓':l.access.unlocked?'←':'قفل'}}</span></button><p v-if="!l.access.unlocked" class="disclaimer">{{l.access.reason==='previous_pending'?'ابتدا درس قبلی را کامل کن.':'پس از دریافت دسترسی دوره باز می‌شود.'}}</p><div v-if="opened===l.id&&l.access.unlocked"><p class="prose">{{l.body}}</p><p v-if="l.homework" class="prose">{{l.homework}}</p><button class="btn btn-primary" :disabled="busy||l.done" @click="complete(l)">{{l.done?'درس تکمیل شده':'این درس را کامل کردم'}}</button></div></article></section></template></main></template>
